[Form]
public class NDXBVEMailRequestControlCenterAIDB extends FormRun implements NDXFormHandlerIncludedI
{
    NDXBVEMailRequestControlCenterAIDBForm formHandler;

}

/// <summary>
/// PaffH 05.11.25
/// </summary>
public void init()
{
    super();
    formHandler = NDXBVEMailRequestControlCenterAIDBForm::newFromForm(element);
}

/// <summary>
/// PaffH 05.11.25
/// </summary>
/// <returns>NDXFormHandler</returns>
public NDXFormHandler parmFormHandler()
{
    return formhandler;
}

/// <summary>
/// PaffH 07.11.25
/// </summary>
public void run()
{
    formHandler.addControls();
    super();
}

/// <summary>
/// PaffH 04.11.25
/// last modified: PaffH 05.12.25
/// </summary>
/// <returns>int</returns>
public int active()
{
    int ret;

    ret = super();

    FormGroupHeader.visible(false);
    FormTabPageRequest.visible(false);
    FormTabPageProject.visible(false);
    FormTabPageContactPerson.visible(false);
    FormTabPageOrganisation.visible(false);
    FormTabPageHeaderAIDBDocument.visible(false);
    FormTabPagePlaner.visible(false);
    FormTabPageInstaller.visible(false);
    FormTabPageBuildingOwner.visible(false);
    FormTabPageADA.visible(false);
    FormTabPageDemand.visible(false);
    FormTabPageLine.visible(false);
    FormTabPageEmail.visible(false);
    switch (NDXBVEMailRequestAIDBHeaderTmp.BVEmailRequestSectionType)
    {
        case NDXBVEmailRequestSectionType::Header :
            FormGroupHeader.visible(true);
            break;
        case NDXBVEmailRequestSectionType::Request:
            FormTabPageRequest.visible(true);
            break;
        case NDXBVEmailRequestSectionType::Project:
            FormTabPageProject.visible(true);
            break;
        case NDXBVEmailRequestSectionType::HeaderAIDBDocument :
            FormTabPageHeaderAIDBDocument.visible(true);
            break;
        case NDXBVEmailRequestSectionType::ContactPerson :
            FormTabPageContactPerson.visible(true);
            break;
        case NDXBVEmailRequestSectionType::Organisation :
            FormTabPageOrganisation.visible(true);
            break;
        case NDXBVEmailRequestSectionType::Planer :
            SysQuery::findOrCreateRange(NDXBVEMailRequestPlaner_DS.queryBuildDataSource(), fieldNum(NDXBVEMailRequestPlaner, RecId)).value(queryValue(NDXBVEMailRequestAIDBHeaderTmp.RefRecId));
            NDXBVEMailRequestPlaner_DS.executeQuery();
            FormTabPagePlaner.visible(true);
            break;
        case NDXBVEmailRequestSectionType::Installer :
            SysQuery::findOrCreateRange(NDXBVEMailRequestInstaller_DS.queryBuildDataSource(), fieldNum(NDXBVEMailRequestInstaller, RecId)).value(queryValue(NDXBVEMailRequestAIDBHeaderTmp.RefRecId));
            NDXBVEMailRequestInstaller_DS.executeQuery();
            FormTabPageInstaller.visible(true);
            break;
        case NDXBVEmailRequestSectionType::BuildingOwner :
            SysQuery::findOrCreateRange(NDXBVEMailRequestBuildingOwner_DS.queryBuildDataSource(), fieldNum(NDXBVEMailRequestBuildingOwner, RecId)).value(queryValue(NDXBVEMailRequestAIDBHeaderTmp.RefRecId));
            NDXBVEMailRequestBuildingOwner_DS.executeQuery();
            FormTabPageBuildingOwner.visible(true);
            break;
        case NDXBVEmailRequestSectionType::ADA :
            SysQuery::findOrCreateRange(NDXBVEMailRequestADA_DS.queryBuildDataSource(), fieldNum(NDXBVEMailRequestADA, RecId)).value(queryValue(NDXBVEMailRequestAIDBHeaderTmp.RefRecId));
            NDXBVEMailRequestADA_DS.executeQuery();
            FormTabPageADA.visible(true);
            break;
        case NDXBVEmailRequestSectionType::Demand :
            FormTabPageDemand.visible(true);
            break;
        case NDXBVEmailRequestSectionType::Email :
            FormTabPageEmail.visible(true);
            break;
        case NDXBVEmailRequestSectionType::ItemLine :
            SysQuery::findOrCreateRange(NDXBVEMailRequestLine_DS.queryBuildDataSource(), fieldNum(NDXBVEMailRequestLine, RecId)).value(queryValue(NDXBVEMailRequestAIDBHeaderTmp.RefRecId));
            NDXBVEMailRequestLine_DS.executeQuery();
            FormTabPageLine.visible(true);
            break;
        default:
            Error(strFmt("@NDXBase:NDXTheElementIsNotTakenIntoAccount", NDXBVEMailRequestAIDBHeaderTmp.BVEmailRequestSectionType));

    }
    formHandler.fillControls(NDXBVEMailRequestAIDBHeaderTmp.BVEmailRequestSectionType);
    return ret;
}

/// <summary>
/// PaffH 04.11.25
/// </summary>
public void linkActive()
{
    if (element.args())
    {
        if (element.args().dataset() == tablenum(NDXBVEMailRequestHeader))
        {
            NDXBVEMailRequestHeader nDXBVEMailRequestHeaderLocal = element.args().record();
            SysQuery::findOrCreateRange(NDXBVEMailRequestHeader_DS.queryBuildDataSource(), 
                fieldNum(NDXBVEMailRequestHeader, RecId))
                .value(queryValue(nDXBVEMailRequestHeaderLocal.RecId));

            NDXBVEMailRequestAIDBHeaderTmp.setTmpData(
                NDXBVEMailRequestAIDBHeaderTmp::fillFromNDXBVEMailRequestHeader(nDXBVEMailRequestHeaderLocal));
            NDXBVEMailRequestAIDBHeaderTmp_DS.executeQuery();
        }
    }
    super();
}

/// <summary>
/// PaffH 18.11.25
/// </summary>
public void init()
{
    super();
    this.query().dataSourceName(this.name()).addRange(fieldNum(NDXBVEMailRequestLineItem, Manual)).value(queryValue(NoYes::No));
}
